def clean(df):
    df = df.copy()
    # Strip whitespace for text columns
    for col in ['Category', 'Region', 'Date']:
        if col in df.columns:
            df[col] = df[col].astype(object).where(df[col].isna(), df[col].astype(str).str.strip())
    # Fix Category label variants (typos, case variants)
    cat_map = {
        'accesories': 'Accessories',
        'accessories': 'Accessories',
        'electronics': 'Electronics',
        'electornics': 'Electronics',
        'furniture': 'Furniture',
        'office supplies': 'Office Supplies',
        'office suplies': 'Office Supplies'
    }
    if 'Category' in df.columns:
        def fix_cat(x):
            if pd.isna(x):
                return x
            s = str(x).strip()
            low = s.lower()
            return cat_map.get(low, s)
        df['Category'] = df['Category'].apply(fix_cat)
    # Fix Region extra spaces / case variants
    if 'Region' in df.columns:
        df['Region'] = df['Region'].apply(lambda x: str(x).strip().title() if pd.notna(x) else x)
    # Ensure numeric types
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # Fix cross-column: Revenue = Quantity * Price
    if all(c in df.columns for c in ['Quantity', 'Price', 'Revenue']):
        df['Revenue'] = df['Quantity'] * df['Price']
    # Fix invalid dates
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    return df

def answer(df):
    # total revenue by category
    if 'Category' not in df.columns or 'Revenue' not in df.columns:
        return {}
    df = df.dropna(subset=['Category'])
    # keep only allowed categories after cleaning (optional)
    grouped = df.groupby('Category', dropna=True)['Revenue'].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # convert numpy types to python int/float
        val = float(v)
        if val.is_integer():
            val = int(val)
        result[str(k)] = val
    return result
